from pathlib import Path
import csv,json
R=Path(__file__).resolve().parent;D=R/'data'
def out(n,rows):
 assert len({v['id'] for v in rows})==len(rows)
 (D/(n+'.json')).write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n','utf8')
 with (D/(n+'.csv')).open('w',encoding='utf-8-sig',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]),delimiter=';');w.writeheader();w.writerows(rows)
 print(n,len(rows))
